 gmenu-dbusmenu-proxy/actions.cpp   | 19 ++++++++++++++
 gmenu-dbusmenu-proxy/actions.h     |  1 +
 gmenu-dbusmenu-proxy/menu.cpp      |  3 +--
 gmenu-dbusmenu-proxy/window.cpp    | 10 ++++++--
 libdbusmenuqt/dbusmenuimporter.cpp | 40 +++++++++++++++++++-----------
 6 files changed, 63 insertions(+), 18 deletions(-)

diff --git a/applets/appmenu/appmenuapplet.cpp b/applets/appmenu/appmenuapplet.cpp
index 79c29a7e32..30c049679d 100644
--- a/applets/appmenu/appmenuapplet.cpp
+++ b/applets/appmenu/appmenuapplet.cpp
@@ -141,6 +141,9 @@ void AppMenuApplet::onMenuAboutToHide()
 {
     auto menuAction = m_currentMenu->menuAction();
