 }

@@ -200,8 +203,13 @@ void AppMenuApplet::trigger(QQuickItem *ctx, int idx)
                     m_sourceMenu->addAction(action);
                 }
                 menuAction->setMenu(m_sourceMenu);
+                if (m_currentMenu->isVisible()) {
+                    Q_EMIT m_sourceMenu->aboutToHide();
+                }
             }
             m_sourceMenu = actionMenu;
+            // We show our own menu instead of the source menu, so let the importer tell the app as if the source menu opened
+            Q_EMIT m_sourceMenu->aboutToShow();
             auto menuAction = m_sourceMenu->menuAction();
             for (QAction *action : m_sourceMenu->actions()) {
                 m_sourceMenu->removeAction(action);
diff --git a/gmenu-dbusmenu-proxy/actions.cpp b/gmenu-dbusmenu-proxy/actions.cpp
index 0962ce2868..4c646679d5 100644
--- a/gmenu-dbusmenu-proxy/actions.cpp
+++ b/gmenu-dbusmenu-proxy/actions.cpp
@@ -87,6 +87,25 @@ void Actions::trigger(const QString &name, const QVariant &target, uint timestam
     });
 }

+void Actions::setState(const QString &name, const QVariant &state)
+{
+    if (!m_actions.contains(name)) {
+        qCWarning(DBUSMENUPROXY) << "Cannot change state of action" << name << "which doesn't exist";
+        return;
+    }
+
+    QDBusPendingReply<void> reply = m_interface->SetState(name, QDBusVariant(state), QVariantMap());
+    auto *watcher = new QDBusPendingCallWatcher(reply, this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, name](QDBusPendingCallWatcher *watcher) {
+        QDBusPendingReply<void> reply = *watcher;
+        if (reply.isError()) {
+            qCWarning(DBUSMENUPROXY) << "Failed to change state of action" << name << "on" << m_interface->service() << "at" << m_interface->path()
+                                     << reply.error();
+        }
+        watcher->deleteLater();
+    });
+}
+
 bool Actions::isValid() const
 {
     return !m_actions.isEmpty();
