     }

-    // GMenu dbus doesn't have any "opened" or "closed" signals, we'll only handle "clicked"
-
     if (eventId == QLatin1String("clicked")) {
         const QVariantMap item = m_currentMenu->getItem(id);
         const QString action = item.value(QStringLiteral("action")).toString();
@@ -395,6 +393,14 @@ void Window::Event(int id, const QString &eventId, const QDBusVariant &data, uin
         if (!action.isEmpty()) {
             triggerAction(action, target, timestamp);
         }
+    } else if (id != 0 && (eventId == QLatin1String("opened") || eventId == QLatin1String("closed"))) {
+        // Some apps, like LibreOffice, only update the items of a submenu while its submenu-action is set
+        const QVariantMap item = m_currentMenu->getItem(id);
+        const QString submenuAction = item.value(QStringLiteral("submenu-action")).toString();
+        QString lookupName;
+        if (Actions *actions = getActionsForAction(submenuAction, lookupName)) {
+            actions->setState(lookupName, eventId == QLatin1String("opened"));
+        }
     }
 }

